import XCTest
@testable import AgentCore

/// Offline tests: key/ID derivation, request signing (byte-for-byte against the
/// Python relay's own implementation), config validation, certificate pinning.
final class RelayClientOfflineTests: XCTestCase {
    // Vector generated by the relay's own code (group-relay/app/auth.py) for a fixed key.
    private let privateKeyB64 = "BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc="
    private let expectedPublicKey = "6kpsY+KcUgq+9VB7Ey7F+ZVHdq6+vnuSQh7qaRRG0iw="
    private let expectedUserID = "u_fe812c12f3ab4ce6ac5db69ac352f906"
    private let expectedSignature = "dBmvEKeB7CxknqZj1znF5ZapCuX+lI+OgfxIS17pEnXG3jrFiF9QPhIM7RiKq17O7/c/7k95iB5K3b7GkflJCg=="

    private func fixedIdentity() throws -> RelayIdentity {
        try RelayIdentity(rawPrivateKey: Data(base64Encoded: privateKeyB64)!)
    }

    func testPublicKeyAndUserIDMatchTheServersDerivation() throws {
        let identity = try fixedIdentity()
        XCTAssertEqual(identity.publicKeyBase64, expectedPublicKey)
        XCTAssertEqual(identity.userID, expectedUserID)
    }

    /// CryptoKit's Ed25519 signatures are randomized, so bytes can't be compared;
    /// instead: (1) the SIGNING STRING must be identical to the server's, which
    /// we prove by verifying the server-generated reference signature over it,
    /// and (2) our own signatures verify. (Swift→Python is covered end to end
    /// by the integration test against the real relay.)
    func testSigningStringMatchesServerAndSignaturesVerify() throws {
        let identity = try fixedIdentity()
        let message = RelayRequestSigner.signingString(
            method: "post", pathWithQuery: "/v1/groups/g_abc/messages?after=3&limit=10",
            timestamp: "1700000000.500", nonce: "NonceNonce1234567890abcd", body: Data(#"{"text":"hi"}"#.utf8)
        )
        XCTAssertTrue(identity.isValidSignature(Data(base64Encoded: expectedSignature)!, for: message),
                      "server-produced signature must verify over our signing string")
        let mine = try identity.sign(message)
        XCTAssertTrue(identity.isValidSignature(mine, for: message))
        XCTAssertFalse(identity.isValidSignature(mine, for: message + Data("x".utf8)))
    }

    func testHeadersContainEverythingTheServerRequires() throws {
        let identity = try fixedIdentity()
        let headers = try RelayRequestSigner.headers(for: identity, method: "GET", pathWithQuery: "/v1/me", body: Data())
        XCTAssertEqual(headers["X-User-Id"], expectedUserID)
        XCTAssertNotNil(Double(headers["X-Timestamp"] ?? ""))
        XCTAssertNotNil(headers["X-Nonce"]?.range(of: "^[A-Za-z0-9_-]{8,64}$", options: .regularExpression))
        XCTAssertFalse((headers["X-Signature"] ?? "").isEmpty)
        let again = try RelayRequestSigner.headers(for: identity, method: "GET", pathWithQuery: "/v1/me", body: Data())
        XCTAssertNotEqual(headers["X-Nonce"], again["X-Nonce"])
    }

    func testIdentityIsCreatedOnceAndReused() async throws {
        let store = InMemoryRelayKeyStore()
        let first = try await RelayIdentityStore.loadOrCreate(in: store)
        let second = try await RelayIdentityStore.loadOrCreate(in: store)
        XCTAssertEqual(first.userID, second.userID)
    }

    func testCorruptStoredKeyIsReplacedNotCrashed() async throws {
        let store = InMemoryRelayKeyStore(Data([1, 2, 3]))
        let identity = try await RelayIdentityStore.loadOrCreate(in: store)
        XCTAssertTrue(identity.userID.hasPrefix("u_"))
        let saved = try await store.load()
        XCTAssertEqual(saved?.count, 32)
    }

    func testFingerprintFormatsNormalize() {
        let hex = String(repeating: "ab", count: 32)
        let colon = (0..<32).map { _ in "AB" }.joined(separator: ":")
        XCTAssertEqual(RelayCertificatePin.normalize(colon), hex)
        XCTAssertEqual(RelayCertificatePin.normalize("sha256 Fingerprint=\(colon)"), hex)
        XCTAssertEqual(RelayCertificatePin.normalize(hex.uppercased()), hex)
    }

    func testPinMatchesOnlyTheExactCertificate() {
        let der = Data("fake-certificate".utf8)
        let pin = RelayCertificatePin.fingerprint(ofDER: der)
        XCTAssertTrue(RelayCertificatePin.matches(der: der, pinned: pin))
        XCTAssertFalse(RelayCertificatePin.matches(der: Data("other".utf8), pinned: pin))
        XCTAssertFalse(RelayCertificatePin.matches(der: der, pinned: "abcd"), "short/garbage pins never match")
        XCTAssertFalse(RelayCertificatePin.matches(der: der, pinned: ""))
    }

    func testConfigValidation() throws {
        let identity = try fixedIdentity()
        let pin = String(repeating: "a", count: 64)
        XCTAssertNoThrow(try RelayClient(config: .init(baseURL: URL(string: "https://10.0.0.5:8443")!, pinnedFingerprint: pin), identity: identity))
        // https without a pin is refused (fail closed).
        XCTAssertThrowsError(try RelayClient(config: .init(baseURL: URL(string: "https://10.0.0.5:8443")!), identity: identity))
        // plain http to a LAN host is refused even if "allowed" — only loopback.
        XCTAssertThrowsError(try RelayClient(config: .init(baseURL: URL(string: "http://10.0.0.5:8443")!, allowInsecureLoopback: true), identity: identity))
        // loopback http only with the explicit dev flag.
        XCTAssertThrowsError(try RelayClient(config: .init(baseURL: URL(string: "http://127.0.0.1:8443")!), identity: identity))
        XCTAssertNoThrow(try RelayClient(config: .init(baseURL: URL(string: "http://127.0.0.1:8443")!, allowInsecureLoopback: true), identity: identity))
        XCTAssertThrowsError(try RelayClient(config: .init(baseURL: URL(string: "ftp://x")!), identity: identity))
    }

    func testRelayErrorPermanence() {
        XCTAssertTrue(RelayError.http(status: 404, detail: "").isPermanent)
        XCTAssertTrue(RelayError.http(status: 401, detail: "").isPermanent)
        XCTAssertFalse(RelayError.http(status: 500, detail: "").isPermanent)
        XCTAssertFalse(RelayError.http(status: 429, detail: "").isPermanent)
        XCTAssertFalse(RelayError.transport("x").isPermanent)
    }
}
